import { TEST_OTPS_COLLECTION_NAME, db } from '~/src/mongo.js'

/**
 * @typedef {object} TestOtpDocument
 * @property {unknown} _id - generated by Mongo
 * @property {string} uid - the interaction uid the code was issued for
 * @property {string} purpose - the authority the code grants
 * @property {string} target - lowercased test email the code was issued to
 * @property {string} code - the code in plain text, for the test to read
 * @property {Date} createdAt - when the record was first written
 * @property {Date} expireAt - checked in-app; Mongo TTL is GC only
 */

/**
 * The test-otps collection (resolved lazily — the `db` live binding is only
 * assigned once `prepareDb` has run)
 */
function coll() {
  return /** @type {Collection<TestOtpDocument>} */ (
    db.collection(TEST_OTPS_COLLECTION_NAME)
  )
}

/**
 * @param {Filter<TestOtpDocument>} filter
 */
export function findOne(filter) {
  return coll().findOne(filter)
}

/**
 * Upserts the record for a {uid, purpose} key, so that a resend replaces the
 * earlier code
 * @param {{ uid: string, purpose: string }} key
 * @param {MatchKeysAndValues<TestOtpDocument>} fields
 */
export async function upsert(key, fields) {
  await coll().updateOne(
    key,
    { $set: fields, $setOnInsert: { createdAt: new Date() } },
    { upsert: true }
  )
}

/**
 * @import { Collection, Filter, MatchKeysAndValues } from 'mongodb'
 */
